from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _ledger(data, revision_first, discounted_tax, refunds, half_up):
    def rounded(numerator):
        if half_up:
            return (numerator + 5000) // 10000
        return numerator // 10000

    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        if revision_first:
            key = (event.get("revision", 0), position)
        else:
            key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = max(0, min(10000, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        base = net if discounted_tax else raw
        tax = rounded(base * event.get("tax_bp", 0))
        value = net + tax
        if refunds and event.get("kind") == "refund":
            value = -value
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + value
    return {"balances": balances}


def _component_06(data):
    packages = data["packages"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    names = sorted(packages, reverse=True)
    best_vector = None
    best = None

    def has_cycle(edges, nodes):
        done = set()
        active = set()

        def visit(name):
            if name in active:
                return True
            if name in done:
                return False
            active.add(name)
            for child in edges.get(name, ()):
                if visit(child):
                    return True
            active.remove(name)
            done.add(name)
            return False

        return any(visit(name) for name in nodes if name not in done)

    def search(selected, constraints, edges):
        nonlocal best, best_vector
        unresolved = [name for name in constraints if name not in selected]
        if not unresolved:
            if has_cycle(edges, selected):
                return
            vector = tuple(selected.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector, best = vector, dict(selected)
            return

        name = max(unresolved)
        low, high = constraints[name]
        versions = sorted((row["version"] for row in packages[name]
                           if low <= row["version"] <= high
                           and row["version"] not in blocked.get(name, [])
                           and (name not in pins or row["version"] == pins[name])),
                          reverse=True)
        for version in versions:
            row = next(row for row in packages[name] if row["version"] == version)
            new_selected = dict(selected)
            new_constraints = dict(constraints)
            new_edges = {key: list(value) for key, value in edges.items()}
            new_selected[name] = version
            deps = []
            valid = True
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                child = dep["name"]
                deps.append(child)
                lo, hi = dep["min"], dep["max"]
                if child in new_constraints:
                    old_lo, old_hi = new_constraints[child]
                    lo, hi = max(lo, old_lo), min(hi, old_hi)
                if lo > hi:
                    valid = False
                    break
                new_constraints[child] = (lo, hi)
                if child in new_selected and not lo <= new_selected[child] <= hi:
                    valid = False
                    break
            if not valid:
                continue
            new_edges[name] = deps
            search(new_selected, new_constraints, new_edges)

    roots = {name: tuple(bounds) for name, bounds in data["roots"].items()}
    search({}, roots, {})
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    n = len(jobs)

    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        chosen = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = {job["id"] for job in chosen}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not (low <= counts.get(group, 0) <= high)
               for group, (low, high) in quotas.items()):
            continue
        active = []
        compatible = True
        for job in sorted(chosen, key=lambda row: (row["start"], row["end"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                compatible = False
                break
        if not compatible:
            continue
        value = sum(job["value"] for job in chosen)
        id_list = tuple(sorted(ids))
        if (best_value is None or value > best_value
                or (value == best_value and id_list > best_ids)):
            best_value, best_ids = value, id_list

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    import heapq

    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    initial_mask = bit_for.get(start_node, 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    initial = (start_node, initial_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], start_node, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, coupons_left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, coupons_left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, coupons_left))
    return {"arrival": None}


